WITH latest_match AS (SELECT s.*, top1.product_category, top1.stock_qty FROM suppliers s LEFT JOIN LATERAL (SELECT c.category AS product_category, c.stock_qty FROM products c WHERE c.supplier_id = s.id ORDER BY c.price DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT CASE WHEN stock_qty >= 312 THEN 'PREMIUM' ELSE 'STANDARD' END AS stock_qty_tier, ROUND(SUM(stock_qty) / NULLIF(COUNT(CASE WHEN product_category = 'Grocery' THEN 1 END), 0), 2) AS stock_qty_per_grocery, PERCENTILE_APPROX(rating, 0.5) AS rating_p50, COUNT(DISTINCT city) AS distinct_cities FROM latest_match GROUP BY 1 HAVING PERCENTILE_APPROX(rating, 0.5) > 0 ORDER BY rating_p50 DESC
